import functools
import re
import unicodedata


class ExpressionError(Exception):
    def __init__(self, expression, start, width, message):
        super().__init__(message)
        self.expression = expression
        self.start = start
        self.width = max(1, width)
        self.message = message

    def diagnostic(self):
        expression = self.expression
        if "\n" not in expression:
            return ("regex parse error:\n    " + expression + "\n    " +
                    " " * self.start + "^" * self.width + "\nerror: " + self.message)
        lines = expression.split("\n")
        result = ["regex parse error:"]
        offset = 0
        for n, line in enumerate(lines, 1):
            result.append("%d: %s" % (n, line))
            if offset <= self.start <= offset + len(line):
                result.append(" " * (len(str(n)) + 2 + self.start - offset) + "^" * self.width)
            offset += len(line) + 1
        result.append("error: " + self.message)
        return "\n".join(result)


def _escape_codepoint(cp):
    if cp <= 0xffff:
        return r"\u%04x" % cp
    return r"\U%08x" % cp


def _ranges(points):
    result = []
    start = last = None
    for cp in points:
        if start is None:
            start = last = cp
        elif cp == last + 1:
            last = cp
        else:
            result.append(_escape_codepoint(start) +
                          ("-" + _escape_codepoint(last) if last != start else ""))
            start = last = cp
    if start is not None:
        result.append(_escape_codepoint(start) +
                      ("-" + _escape_codepoint(last) if last != start else ""))
    return "".join(result)


