        return (cat[0] in "LM" or cat in ("Nd", "Nl", "Pc") or
                cp in (0x200c, 0x200d) or 0x24b6 <= cp <= 0x24e9)
    return _ranges(cp for cp in range(0x110000) if is_word(cp))


