    result = []
    in_class = False
    i = 0
    # Most inputs are ASCII. Still, boundaries must treat adjacent Unicode
    # characters as word characters even when the expression spells ASCII.
    wc = word_contents() if unicode_classes else r"a-zA-Z0-9_"
    w = "[" + wc + "]"
    nw = "[^" + wc + "]"
    boundary = "(?:(?<!" + w + ")(?=" + w + ")|(?<=" + w + ")(?!" + w + "))"
    non_boundary = "(?:(?<=" + w + ")(?=" + w + ")|(?<!" + w + ")(?!" + w + "))"
    while i < len(expression):
        ch = expression[i]
        if ch == "\\" and i + 1 < len(expression):
            nxt = expression[i + 1]
            if nxt in "pP":
                if i + 2 < len(expression) and expression[i+2] == "{":
                    end = expression.find("}", i+3)
                    name = expression[i+3:end]
                else:
                    end = i + 2
                    name = expression[end:end+1]
                try:
                    content = property_contents(name)
                except ValueError:
                    raise ExpressionError(expression, i, end-i+1, "Unicode property not found")
                result.append(("[" if nxt == "p" else "[^") + content + "]")
                i = end + 1
                continue
            if nxt in "wW":
                if in_class and nxt == "w":
                    result.append(wc)
                else:
                    result.append(w if nxt == "w" else nw)
            elif nxt in "sS":
                if in_class and nxt == "s":
                    result.append(SPACE_CONTENTS)
                else:
                    result.append(("[" if nxt == "s" else "[^") + SPACE_CONTENTS + "]")
            elif nxt in "bB" and not in_class:
                result.append(boundary if nxt == "b" else non_boundary)
            elif nxt == "z":
                result.append(r"\Z")
