                    result.append(wc)
                else:
                    result.append(w if nxt == "w" else nw)
            elif nxt in "sS":
                if in_class and nxt == "s":
                    result.append(SPACE_CONTENTS)
                else:
                    result.append(("[" if nxt == "s" else "[^") + SPACE_CONTENTS + "]")
            elif nxt in "bB" and not in_class:
                result.append(boundary if nxt == "b" else non_boundary)
            elif nxt == "z":
                result.append(r"\Z")
            elif nxt == "x" and expression[i+2:i+3] == "{":
                end = expression.find("}", i+3)
                if end < 0:
                    raise ExpressionError(expression, i, len(expression)-i, "incomplete escape sequence, reached end of pattern prematurely")
                try:
                    result.append(_escape_codepoint(int(expression[i+3:end], 16)))
                except ValueError:
                    raise ExpressionError(expression, i, end-i+1, "invalid hexadecimal digit")
                i = end + 1
                continue
            else:
                result.append(ch + nxt)
            i += 2
            continue
        if ch == "[":
            in_class = True
        elif ch == "]":
            in_class = False
        # Python's $ has a before-final-newline exception. Inputs do not include
        # a newline, but a literal \n in a plugin or filter may be significant.
        result.append(ch)
        i += 1
    output = "".join(result)
    output = re.sub(r"\(\?<([A-Za-z_][A-Za-z_0-9]*)>", r"(?P<\1>", output)
    return output


class Pattern:
    def __init__(self, expression, compiled):
        self.expression = expression
        self.compiled = compiled

    def finditer(self, text):
        return self.compiled.finditer(text)

    def search(self, text):
        return self.compiled.search(text)


@functools.lru_cache(maxsize=256)
def compile_expression(expression):
    _validate(expression)
    try:
        translated = translate(expression)
        compiled = re.compile(translated)
    except re.error as e:
        # Report locations in the user's expression, not the expanded Unicode
        # tables. Re-parsing the original commonly gives the exact location.
        try:
            re.compile(expression)
        except re.error as original:
            e = original
        start = min(getattr(e, "pos", 0) or 0, max(0, len(expression)-1))
        message = str(e).split(" at position", 1)[0]
        if "nothing to repeat" in message:
            message = "repetition operator missing expression"
        elif "bad character range" in message:
            message = "invalid character class range, the start must be <= the end"
        elif "min repeat greater than max repeat" in message:
            message = "invalid repetition count range, the start must be <= the end"
        elif "unknown extension" in message:
            message = "unrecognized flag"
        elif "bad escape" in message:
            message = "unrecognized escape sequence"
        raise ExpressionError(expression, start, 1, message) from None
    return Pattern(expression, compiled)
