def spelling(name):
    return "--" + name + (" <" + name + ">" if LONG[name][2] else "")


def help_text(program):
    text = ("Note: All extraction features (e.g: -i) work on a specified file (-f) or an output stream.\n\n"
            "Usage: " + program + " [OPTIONS]\n\nOptions:\n")
    for name, short, takes_value, description in SPEC:
        label = ("  -" + short + ", " if short else "      ") + spelling(name)
        text += label.ljust(30) + description + "\n"
    return text


def _jaro_winkler(a, b):
    if a == b:
        return 1.0
    if not a or not b:
        return 0.0
    radius = max(len(a), len(b)) // 2 - 1
    radius = max(0, radius)
    am = [False] * len(a)
    bm = [False] * len(b)
    matches = 0
    for i, c in enumerate(a):
        for j in range(max(0, i - radius), min(len(b), i + radius + 1)):
            if not bm[j] and b[j] == c:
                am[i] = bm[j] = True
                matches += 1
                break
    if not matches:
        return 0.0
    seq1 = [a[i] for i in range(len(a)) if am[i]]
    seq2 = [b[i] for i in range(len(b)) if bm[i]]
    transpositions = sum(x != y for x, y in zip(seq1, seq2)) / 2
    score = (matches / len(a) + matches / len(b) +
             (matches - transpositions) / matches) / 3
    prefix = 0
    for x, y in zip(a, b):
        if x != y or prefix == 4:
            break
        prefix += 1
    if score > 0.7:
        score += prefix * 0.1 * (1 - score)
    return score


def suggestions(name):
    best = None
    score = 0.8
    for candidate in LONG:
        similarity = _jaro_winkler(name, candidate)
        if similarity > score:
            best, score = candidate, similarity
    return best


class Parser:
    def __init__(self, program):
        self.program = program
        self.seen = []
        self.values = {name: ("" if val else False) for name, short, val, desc in SPEC}

    def usage(self, seen=None):
        if seen is None:
            seen = self.seen
        return "Usage: " + self.program + " " + (" ".join(spelling(n) for n in seen) if seen else "[OPTIONS]")

    def error(self, message, seen=None, show_usage=True, tip=""):
        text = "error: " + message + "\n\n"
        if tip:
            text += "  tip: " + tip + "\n\n"
        if show_usage:
            text += self.usage(seen) + "\n\n"
        sys.stderr.write(text + FOOTER)
        raise SystemExit(2)

    def unexpected(self, argument):
        if argument.startswith("--") and len(argument) > 2:
            # Long-option errors retain previously parsed options in usage.
            name = argument[2:].split("=", 1)[0]
            suggestion = suggestions(name)
            seen = list(self.seen)
            tip = ""
            if suggestion:
                if suggestion not in seen:
                    seen.append(suggestion)
                tip = "a similar argument exists: '--" + suggestion + "'"
            self.error("unexpected argument '" + argument.split("=", 1)[0] + "' found", seen=seen, tip=tip)
        self.error("unexpected argument '" + argument + "' found", seen=[])

    def add(self, name, value):
        if name in self.seen:
            self.error("the argument '" + spelling(name) + "' cannot be used multiple times", seen=[])
        self.seen.append(name)
        self.values[name] = value
        if name == "help":
            sys.stdout.write(help_text(self.program))
            raise SystemExit(0)
        if name == "version":
            sys.stdout.write(VERSION)
            raise SystemExit(0)

    def parse(self, args):
        i = 0
        while i < len(args):
            arg = args[i]
            if arg == "--":
                if i + 1 < len(args):
                    self.error("unexpected argument '" + args[i+1] + "' found", seen=[])
                break
            if arg.startswith("--"):
                name, separator, value = arg[2:].partition("=")
                if name not in LONG:
                    self.unexpected(arg)
                takes_value = LONG[name][2]
                if not takes_value and separator:
                    self.error("unexpected value '" + value + "' for '--" + name + "' found; no more were expected",
                               seen=self.seen + ([name] if name not in self.seen else []))
                if takes_value:
                    if not separator:
                        i, value = self.take_value(name, args, i)
                    self.add(name, value)
                else:
                    self.add(name, True)
            elif arg.startswith("-") and arg != "-":
                j = 1
                while j < len(arg):
                    short = arg[j]
                    if short not in SHORT:
                        self.unexpected("-" + short)
                    name, _, takes_value, _ = SHORT[short]
                    if takes_value:
                        value = arg[j+1:]
                        if value.startswith("="):
                            value = value[1:]
                            self.add(name, value)
                        elif value:
                            self.add(name, value)
                        else:
                            i, value = self.take_value(name, args, i)
                            self.add(name, value)
                        break
                    self.add(name, True)
                    j += 1
            else:
                self.unexpected(arg)
            i += 1
        return self.values

    def take_value(self, name, args, i):
        if i+1 < len(args) and (not args[i+1].startswith("-") or args[i+1] == "-"):
            return i+1, args[i+1]
        if i+1 < len(args):
            following = args[i+1]
            if following.startswith("--") and following not in ("--",):
                next_name = following[2:].split("=", 1)[0]
                if next_name not in LONG:
                    self.unexpected(following)
            elif len(following) > 1 and following[1] not in SHORT:
                self.unexpected("-" + following[1])
        self.error("a value is required for '" + spelling(name) + "' but none was supplied", show_usage=False)
