"""Formatting for the terminal stream and the append-only result file."""
import sys


class Output:
    def __init__(self, options):
        self.options = options
        self.file = None
        if options["output"]:
            try:
                self.file = open(options["output"], "a", encoding="utf-8", newline="")
            except OSError:
                if not options["ignore"]:
                    print("[-] Failed to open output file: " + options["file"])
                raise SystemExit(1)
            labels = []
            if not options["hide"]:
                labels.append("content_type")
            if options["display"]:
                labels.append("file")
            if options["line"]:
                labels.append("line")
            labels.append("data")
            self.file.write(", ".join(labels) + "\n")
            self.file.flush()

    def emit(self, kind, text, filename, number):
        opt = self.options
        if self.file:
            fields = []
            if not opt["hide"]:
                fields.append(kind)
            if opt["display"]:
                fields.append(filename)
            if opt["line"]:
                fields.append(str(number))
            fields.append(text)
            self.file.write(", ".join(fields) + "\n")
        else:
            prefix = ""
            if not opt["hide"]:
                prefix = kind + (", " if opt["display"] or opt["line"] else ": ")
            if opt["display"]:
                prefix += "file: " + filename + " "
            suffix = ", line: " + str(number) if opt["line"] else ""
            sys.stdout.write(prefix + text + suffix + "\n")

    def close(self):
        if self.file:
            self.file.close()
