"""Local plugin-file handling and offline management diagnostics."""
import json
import os
import pwd
import sys


def config_path():
    home = os.environ.get("HOME")
    if home is None:
        try:
            home = pwd.getpwuid(os.getuid()).pw_dir
        except (KeyError, OSError):
            home = ""
    return home + "/.DataSurgeon/plugins.json"


def _continue_after_error():
    print("[-] Error: Failed to parse plugins.json. Please ensure all required fields are present.")
    while True:
        print("[+] Do you want to exit? (y/n): ", flush=True)
        answer = sys.stdin.buffer.readline().decode("utf-8", errors="replace").strip()
        if answer.lower() == "y":
            raise SystemExit(1)
        if answer.lower() == "n":
            return
        print("[-] Invalid input. Please enter 'y' or 'n'.")
        if not answer:
            # Avoid an unbounded loop when there is no interactive input.
            raise SystemExit(1)


def load():
    path = config_path()
    try:
        with open(path, "r", encoding="utf-8") as source:
            content = source.read()
    except (OSError, UnicodeError):
        print("Failed to open plugins.json file. PLUGIN_PATH: " + path)
        return []
    try:
        data = json.loads(content)
        if not isinstance(data, list):
            raise ValueError()
        # Empty configurations require no plugin-specific runtime.
        if data:
            raise ValueError()
    except (ValueError, TypeError):
        _continue_after_error()
        return []
    return data


def manage(options):
    if options["list"]:
        data = load()
        if not data:
            print("No plugins found. Plugin File: " + config_path())
        raise SystemExit(1)
    if options["remove"] or options["update"]:
        load()
        raise SystemExit(1)
    if options["add"]:
        # Network plugin installation is intentionally not used by this
        # independent implementation. It has no remote runtime dependency.
        raise SystemExit(1)
