"""Entry point, streaming input, and extraction/output orchestration."""
import os
import stat
import sys
import time

from . import plugins
from .options import Parser
from .render import Output
from .rx import compile_expression, ExpressionError
from .scanners import build_scanners


READING = "[*] Reading standard input. If you meant to analyze a file use 'ds -f <FILE>' (ctrl+c to exit)"


def regex_failure(error, which):
    line = "595:54" if which == "drop" else "598:58"
    bar = "~" * 79
    sys.stderr.write(
        "\nthread 'main' (" + str(os.getpid()) + ") panicked at src/main.rs:" + line + ":\n"
        "called `Result::unwrap()` on an `Err` value: Syntax(\n" + bar + "\n" +
        error.diagnostic() + "\n" + bar + "\n)\n"
        "note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n"
    )
    raise SystemExit(101)


def valid_lines(stream):
    """Yield UTF-8 lines; malformed lines are skipped without advancing numbering."""
    while True:
        try:
            line = stream.readline()
        except (OSError, ValueError):
            return
        if not line:
            return
        if line.endswith(b"\n"):
            line = line[:-1]
            if line.endswith(b"\r"):
                line = line[:-1]
        try:
            yield line.decode("utf-8")
        except UnicodeDecodeError:
            continue


def files_below(root, is_root=True):
    """Depth-first traversal in filesystem order, without descending through links."""
    try:
        st = os.lstat(root)
    except OSError:
        return
    if stat.S_ISREG(st.st_mode):
        yield root
    elif stat.S_ISDIR(st.st_mode) or (is_root and stat.S_ISLNK(st.st_mode) and os.path.isdir(root)):
        try:
            with os.scandir(root) as iterator:
                entries = list(iterator)
        except OSError:
            return
        for entry in entries:
            yield from files_below(os.path.join(root, entry.name), False)


class Extractor:
    def __init__(self, options, output, scanners, drop, include):
        self.options = options
        self.output = output
        self.scanners = scanners
        self.drop = drop
        self.include = include

    def allowed(self, text):
        return not (self.drop and self.drop.search(text)) and not (self.include and not self.include.search(text))

    def process_line(self, line, filename, number):
        seen = set()
        for kind, pattern in self.scanners:
            for match in pattern.finditer(line):
                if not self.options["clean"] and self.allowed(line):
                    self.output.emit(kind, line, filename, number)
                    if not self.options["thorough"]:
                        return
                text = match.group(0)
                if text not in seen and self.allowed(text):
                    self.output.emit(kind, text, filename, number)
                    seen.add(text)
                    if not self.options["thorough"]:
                        return

    def stream(self, source, filename):
        for number, line in enumerate(valid_lines(source), 1):
            self.process_line(line, filename, number)

    def file(self, path):
        try:
            source = open(path, "rb")
        except OSError:
            if not self.options["ignore"]:
                print("[-] File not found: " + path)
            raise SystemExit(1)
        with source:
            self.stream(source, path)


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    # Keep control characters and original line endings unchanged on output.
    if hasattr(sys.stdout, "reconfigure"):
        sys.stdout.reconfigure(encoding="utf-8", errors="replace", newline="", line_buffering=True)
        sys.stderr.reconfigure(encoding="utf-8", errors="replace", newline="")
    plugins.load()
    program = os.path.basename(sys.argv[0]) or "executable"
    options = Parser(program).parse(argv)
    plugins.manage(options)
    start = time.monotonic()
    compiled = {}
    for key in ("drop", "filter"):
        try:
            compiled[key] = compile_expression(options[key]) if options[key] else None
        except ExpressionError as error:
            regex_failure(error, key)
    scanners = build_scanners(options)
    output = Output(options)
    extractor = Extractor(options, output, scanners, compiled["drop"], compiled["filter"])
    try:
        if options["file"]:
            extractor.file(options["file"])
        elif options["directory"]:
            for path in files_below(options["directory"]):
                extractor.file(path)
        else:
            if not options["suppress"]:
                print(READING, flush=True)
            extractor.stream(sys.stdin.buffer, "")
    finally:
        output.close()
    if options["time"]:
        duration = int(time.monotonic() - start)
        hours = duration // 3600
        minutes = duration // 60 % 60
        seconds = duration % 60
        print("[*] Time elapsed: %02dh:%02dm:%02ds" % (hours, minutes, seconds))
    return 0
