#!/bin/sh
# Build a self-contained executable archive using the system Python runtime.
# All modules use the standard library, so no network-installed dependencies
# are required, including on a clean checkout.
set -eu
cd "$(dirname "$0")"
command -v python3 >/dev/null 2>&1 || {
    echo 'Python 3 is required to build and run this program.' >&2
    exit 1
}
target=${1:-./executable}
