import os
import pathlib
import shutil
import sys
import tempfile
import zipapp

root = pathlib.Path.cwd()
target = pathlib.Path(sys.argv[1])
target.parent.mkdir(parents=True, exist_ok=True)
with tempfile.TemporaryDirectory(prefix='package-', dir=root / '.build') as staging:
    staging = pathlib.Path(staging)
    shutil.copytree(root / 'surgeon', staging / 'surgeon',
                    ignore=shutil.ignore_patterns('__pycache__', '*.pyc'))
    archive = root / '.build' / 'program.tmp'
    zipapp.create_archive(staging, archive,
                          interpreter='/usr/bin/env python3',
                          main='surgeon.cli:main', compressed=True)
    archive.chmod(0o755)
    os.replace(archive, target)
