def _kind(value):
    if value is None:
        return "null"
    if isinstance(value, dict):
        return "map"
    if isinstance(value, list):
        return "sequence"
    if isinstance(value, bool):
        return "boolean `" + str(value).lower() + "`"
    if isinstance(value, str):
        return "string " + json.dumps(value, ensure_ascii=False)
    return "integer `" + str(value) + "`"


def parse_metadata(text):
    try:
        value = json.loads(text)
    except ValueError as e:
        if isinstance(e, json.JSONDecodeError):
            if not text.strip():
                raise ValueError("EOF while parsing a value at line 1 column 0") from None
            raise ValueError("expected value at line %d column %d" % (e.lineno, e.colno)) from None
        raise
    if not isinstance(value, list):
        column = 0 if isinstance(value, dict) else len(text.rstrip())
        raise ValueError("invalid type: %s, expected a sequence at line 1 column %d" % (_kind(value), column))
    result = []
    offset = 0
    for record in value:
        end = text.find("}", offset)
        offset = end+1 if end != -1 else len(text)
        prefix = text[:offset]
        line = prefix.count("\n")+1
        column = len(prefix.rsplit("\n", 1)[-1])
        if not isinstance(record, dict):
            raise ValueError("invalid type: %s, expected struct Plugin at line %d column %d" % (_kind(record), line, column))
        for field in FIELDS:
            if field not in record:
                raise ValueError("missing field `%s` at line %d column %d" % (field, line, column))
            if not isinstance(record[field], str):
                raise ValueError("invalid type: %s, expected a string at line %d column %d" % (_kind(record[field]), line, column))
        result.append({field: record[field] for field in FIELDS})
    return result


def load():
    path = config_path()
    try:
        with open(path, "r", encoding="utf-8") as source:
            content = source.read()
    except (OSError, UnicodeError):
        print("Failed to open plugins.json file. PLUGIN_PATH: " + path)
        return []
    try:
        return parse_metadata(content)
    except ValueError:
        _continue_after_error()
        return []


def _save(records):
    try:
        # The metadata file is expected to exist already; management does not
        # create a missing configuration directory or file.
        with open(config_path(), "r+", encoding="utf-8", newline="") as target:
            target.seek(0)
            target.write(json.dumps(records, ensure_ascii=False, separators=(",", ":")))
            target.truncate()
        return True
    except OSError:
        print("[-] Error: Failed to open plugins.json file.")
        return False


def _fetch(url):
    base = url.rstrip("/")
    request_url = base.replace("github.com", "raw.githubusercontent.com") + "/main/plugins.json"
    parsed = urllib.parse.urlsplit(request_url)
    reason = None
    if not parsed.scheme:
        reason = "builder error: relative URL without a base"
    elif parsed.scheme not in ("http", "https"):
        reason = "builder error: URL scheme is not allowed"
    if reason is None:
        try:
            request = urllib.request.Request(request_url)
            try:
                response = urllib.request.urlopen(request, timeout=30)
            except urllib.error.HTTPError as e:
                response = e
            with response:
                data = response.read().decode("utf-8", errors="replace")
            records = parse_metadata(data)
            for record in records:
                record["source_url"] = record["source_url"].rstrip("/")
            return records
        except ValueError as e:
            reason = str(e)
        except (OSError, urllib.error.URLError) as e:
            reason = "error sending request for url (" + request_url + ")"
    sys.stderr.write("[-] Error: Failed to parse plugins.json from the provided URL. Reason: " + reason + "\n")
    raise SystemExit(1)


def _listing(records):
    if not records:
        print("No plugins found. Plugin File: " + config_path())
        return
    print("Plugin File: " + config_path() + "\n")
    rows = [["Source URL", "Version", "Argument Long Name"]]
    rows += [[p["source_url"], p["version"], p["arg_long_name"]] for p in records]
    widths = [max(len(row[i].encode("utf-8")) for row in rows) for i in range(3)]
    for row in rows:
        print(" | ".join(value.ljust(width) for value, width in zip(row, widths)))


def manage(options):
    if options["list"]:
        _listing(load())
        raise SystemExit(1)
    if options["add"]:
        incoming = _fetch(options["add"])
        records = load()
        for plugin in incoming:
            if any(p["arg_long_name"] == plugin["arg_long_name"] for p in records):
                print("[-] Error: Skipping Duplicate plugin found with arg_long_name: " + plugin["arg_long_name"])
            else:
                records.append(plugin)
                if _save(records):
                    print("[*] Download and added plugin: " + options["add"])
        if not incoming:
            _save(records)
        raise SystemExit(1)
    if options["remove"]:
        url = options["remove"]
        records = load()
        kept = [p for p in records if p["source_url"].rstrip("/") != url.rstrip("/")]
        if len(kept) < len(records) and _save(kept):
            print("[*] Removed plugin: " + url)
        raise SystemExit(1)
    if options["update"]:
        url = options["update"]
        records = load()
        if url == "all":
            targets = list(dict.fromkeys(p["source_url"].rstrip("/") for p in records))
        elif any(p["source_url"].rstrip("/") == url.rstrip("/") for p in records):
            targets = [url]
        else:
            print("[-] Error: No existing plugin found with the given URL: " + url)
            raise SystemExit(1)
        for target in targets:
            incoming = _fetch(target)
            records = [p for p in records if p["source_url"].rstrip("/") != target.rstrip("/")]
            records.extend(incoming)
            if _save(records):
                print("[*] Updated Plugin: " + target)
        raise SystemExit(1)
