    if options["remove"]:
        url = options["remove"]
        records = load()
        kept = [p for p in records if p["source_url"].rstrip("/") != url.rstrip("/")]
        if len(kept) < len(records) and _save(kept):
            print("[*] Removed plugin: " + url)
        raise SystemExit(1)
    if options["update"]:
        url = options["update"]
        records = load()
        if url == "all":
            targets = list(dict.fromkeys(p["source_url"].rstrip("/") for p in records))
        elif any(p["source_url"].rstrip("/") == url.rstrip("/") for p in records):
            targets = [url]
        else:
            print("[-] Error: No existing plugin found with the given URL: " + url)
            raise SystemExit(1)
        for target in targets:
            incoming = _fetch(target)
            records = [p for p in records if p["source_url"].rstrip("/") != target.rstrip("/")]
            records.extend(incoming)
            if _save(records):
                print("[*] Updated Plugin: " + target)
